    if (on.agencyId && on.agencyName === name) return on.agencyId;
    var g = identity();
    var r = await M.api.rpc('va_claim_agency', { p_token: g.token, p_variant: VARIANT, p_name: name, p_name_key: norm(name), p_agency_id: on.agencyId || null });
    if (!r || !r.ok) { var e1 = new Error(reasonText(r, { '名': name })); e1.user = true; throw e1; }
    await ctx().save(function (s) { var o = normOnline(s); o.agencyId = r.id; o.agencyName = name; });
    return r.id;
  }
  // 签约取艺名时问一句（shacho.js 的 checkStageNameRemote 换成这个）。连不上 / 关了联机 = 放行
  async function checkStageName(name) {
    if (!online() || !M.api) return true;
    try { return (await M.api.rpc('va_stage_free', { p_variant: VARIANT, p_stage_key: norm(name), p_token: identity().token })) !== false; }
    catch (e) { markOffline(e); return true; }
  }

  // ═════════════════════════ 上架 ═════════════════════════
  // 步骤：过滤 → 登记事务所 → 混音（shacho 的 renderWorkAudio）→ 压 mp3 → 领上传票 → 传文件 → 登记作品
  async function uploadWork(localId, form) {
    var c = ctx(), st = c.readState(), w = (st.works || []).find(function (x) { return x.id === localId; });
    var up = M.ui.up = { id: localId, stage: 'check', err: '', done: false };
    function step(s) { up.stage = s; rerender(); }
    function fail(msg) { up.err = msg; up.stage = 'form'; rerender(); return { ok: false, msg: msg }; }
    if (!w) return fail('找不到这部作品');
    if (!online()) return fail(isOff() ? '联机关着。先在市场页打开联机。' : '服务器暂时连不上，过一会儿再试。');
    if (onlineOf(st).listed && onlineOf(st).listed[localId]) return fail(REASON.dup);
    if (!form || !form.confirmed) return fail('上架前要勾一下确认：作品的声音和文字会公开给所有玩家。');
    var script = c.scriptOf ? c.scriptOf(w) : null;
    var agency = c.agencyName ? c.agencyName(st) : ((st.agency && st.agency.name) || '');
    var L0 = buildListing(w, agency, form, script);
    if (L0.err) return fail(L0.err);
    var row = L0.row;
    try {
      step('agency');
      var aid = await ensureAgency();
      step('mix');
      if (!c.renderAudio) throw new Error('这个版本还不能混音');
      var audio = await c.renderAudio(w, function (i, n) { up.stage = 'mix'; up.prog = i + '/' + n; rerender(); });
      step('mp3');
      var lame = await loadLame();
      var mp3 = encodeMp3(lame, audio);
      if (mp3.bytes > MK.maxBytes) return fail('压完还有 ' + Math.round(mp3.bytes / 1024) + ' KB，超过 1.5 MB 上限了。');
      var g = identity();
      step('ticket');
      var tk = await M.api.rpc('va_begin_upload', { p_token: g.token, p_agency_id: aid, p_variant: VARIANT, p_bytes: mp3.bytes });
      if (!tk || !tk.ok) return fail(reasonText(tk));
      step('upload');
      var Bl = c.Blob || G.Blob;
      await M.api.upload(tk.path, new Bl(mp3.chunks, { type: 'audio/mpeg' }));
      step('publish');
      var pub = await M.api.rpc('va_publish', { p_token: g.token, p_agency_id: aid, p_path: tk.path, p_local_id: row.local_id, p_title: row.title, p_blurb: row.blurb,
        p_tags: row.tags, p_tier: row.tier, p_stage_name: row.stage_name, p_stage_key: row.stage_key, p_price: row.price, p_duration: mp3.sec });
      if (!pub || !pub.ok) return fail(reasonText(pub, { '艺名': row.stage_name, '别家': (pub && pub.owner) || '别家' }));
      await c.save(function (s) {
        var o = normOnline(s); o.listed[localId] = pub.id; o.stats[localId] = { sales: 0, stars: 0, n: 0, hidden: false };
        if (C().addNews) C().addNews(s, '《' + row.title + '》上架联机市场，每次 ' + money(row.price));
      });
      up.stage = 'done'; up.done = true; up.serverId = pub.id; up.truncated = mp3.truncated; up.sec = mp3.sec; up.kb = Math.round(mp3.bytes / 1024);
      M.data.list = null;   // 新作榜重拉
      rerender();
      toast('success', '《' + row.title + '》上架了' + (mp3.truncated ? '（超过 3 分钟，截到了 3 分钟）' : '') + '。');
      return { ok: true, id: pub.id, row: row, mp3: { bytes: mp3.bytes, sec: mp3.sec, truncated: mp3.truncated } };
    } catch (e) {
      markOffline(e);
      return fail(e && e.user ? e.message : '没上架成功：' + ((e && e.message) || e));
    }
  }

  // ═════════════════════════ 逛市场：列表 / 排行 / 作品页 / 社团页 / 声优页 ═════════════════════════
  function workRows(a) { return (Array.isArray(a) ? a : []).map(function (w) { w.tags = Array.isArray(w.tags) ? w.tags : []; return w; }); }
  async function load(key, fn) {
    if (M.busy[key]) return;
    M.busy[key] = true; M.err[key] = ''; rerender();
    try { await fn(); }
    catch (e) { markOffline(e); M.err[key] = (e && e.message) || String(e); }
    finally { M.busy[key] = false; rerender(); }
  }
  function loadList() {
    var u = M.ui;
    return load('list', async function () {
      var r = await M.api.rpc('va_search', { p_variant: VARIANT, p_q: u.q || '', p_tag: u.tag || '', p_tier: u.tier || '', p_sort: u.sort, p_limit: MK.pageSize, p_offset: u.page * MK.pageSize });
      M.data.list = workRows(r && r.rows); M.data.total = Number(r && r.total) || 0;
      if (!M.data.tags) { try { M.data.tags = await M.api.rpc('va_tags', { p_variant: VARIANT, p_limit: 24 }) || []; } catch (e) { M.data.tags = []; } }
    });
  }
  function rankKey() { return M.ui.rank + ':' + M.ui.period + ':' + (M.ui.rank === 'works' ? M.ui.tier : ''); }
  function loadRank() {
    var u = M.ui, k = rankKey();
    return load('rank', async function () {
      var r = u.rank === 'works' ? await M.api.rpc('va_rank_works', { p_variant: VARIANT, p_period: u.period, p_tier: u.tier || null, p_limit: 30 })
        : u.rank === 'talents' ? await M.api.rpc('va_rank_talents', { p_variant: VARIANT, p_period: u.period, p_limit: 30 })
        : await M.api.rpc('va_rank_agencies', { p_variant: VARIANT, p_period: u.period, p_limit: 50 });
      M.data.rank[k] = u.rank === 'works' ? workRows(r) : (Array.isArray(r) ? r : []);
    });
  }
  function loadBoard() {
    return load('board', async function () { M.data.board = parseBoard(await M.api.rpc('va_rank_agencies', { p_variant: VARIANT, p_period: '30d', p_limit: 50 })); });
  }
  function loadWork(id) { return load('work', async function () { var r = await M.api.rpc('va_work_page', { p_work_id: Number(id) }); M.data.work = r && r.work ? { work: workRows([r.work])[0], reviews: r.reviews || [], dist: r.dist || {} } : { gone: true }; }); }
  function loadAgency(id) { return load('agency', async function () { var r = await M.api.rpc('va_agency_page', { p_agency_id: id }); M.data.agency = r && r.agency ? { agency: r.agency, board: r.board || {}, works: workRows(r.works), talents: r.talents || [], fines: r.fines || [] } : { gone: true }; }); }
  function loadTalent(id) { return load('talent', async function () { var r = await M.api.rpc('va_talent_page', { p_talent_id: id }); M.data.talent = r && r.talent ? { talent: r.talent, works: workRows(r.works) } : { gone: true }; }); }

  // 联机榜：服务器的事务所 + lists.js 里那 8 家 NPC（市值用单机榜同一套漂动），按市值排
  function parseBoard(rows) {
    return (Array.isArray(rows) ? rows : []).map(function (r) {
      return { id: r.id, name: String(r.name || ''), cap: Number(r.cap) || 0, revenue: Number(r.income_30d) || 0, income: Number(r.income) || 0, fined: Number(r.fined) || 0,
        works: Number(r.works) || 0, talents: Number(r.talents) || 0, hit: r.best ? '《' + r.best + '》' : '—', npc: false };
    });
  }
  function mergedBoard(st, server) {
    var c = C(), npc = [];
    try { npc = (c.marketBoard ? c.marketBoard(st, '') : []).filter(function (r) { return !r.me; }).map(function (r) { return { name: r.name, cap: r.cap, revenue: r.revenue, talents: r.talents, hit: r.hit, npc: true, fined: 0 }; }); } catch (e) {}
    var myId = onlineOf(st).agencyId, names = {};
    var rows = (server || []).map(function (r) { var x = Object.assign({}, r); x.me = !!myId && r.id === myId; names[r.name] = 1; return x; });
    npc.forEach(function (r) { if (!names[r.name]) rows.push(r); });   // 真人抢了 NPC 的名字 → 真人那家留着
    rows.sort(function (a, b) { return b.cap - a.cap; });
    rows.forEach(function (r, i) { r.rank = i + 1; });
    return rows;
  }

  // ═════════════════════════ 听：试听 10 秒 / 付费听整部 ═════════════════════════
  function findWork(id) {
    id = Number(id);
    var pools = [M.data.list || [], (M.data.work && M.data.work.work) ? [M.data.work.work] : [], (M.data.agency && M.data.agency.works) || [], (M.data.talent && M.data.talent.works) || []];
    Object.keys(M.data.rank).forEach(function (k) { if (/^works:/.test(k)) pools.push(M.data.rank[k]); });
    for (var i = 0; i < pools.length; i++) { var w = pools[i].find(function (x) { return Number(x.id) === id; }); if (w) return w; }
    var f = favList().find(function (x) { return Number(x.id) === id; });
    return f || null;
  }
  function stopPlay() {
    var p = M.player;
    if (p.el) { try { p.el.pause(); } catch (e) {} try { p.el.src = ''; } catch (e) {} }
    if (p.timer) clearTimeout(p.timer);
    M.player = { id: null, mode: null, el: null };
  }
  function play(w, mode) {
    stopPlay();
    var c = ctx(); if (c.stopAudio) { try { c.stopAudio(); } catch (e) {} }
    var A = c.Audio || G.Audio; if (!A) { toast('warning', '这个浏览器放不了声音'); return; }
    var el = new A(M.api.publicUrl(w.audio_path)), id = Number(w.id);
    M.player = { id: id, mode: mode, el: el };
    function end() { if (M.player.el === el) { stopPlay(); rerender(); } }
    if (mode === 'preview') {
      el.addEventListener('timeupdate', function () { if (el.currentTime >= MK.previewSec) { end(); toast('info', '试听到这儿。想听完整部，付 ' + money(w.price) + '。'); } });
      M.player.timer = setTimeout(end, 40000);   // 加载太慢的兜底
    }
    el.addEventListener('ended', end);
    el.addEventListener('error', function () { if (M.player.el === el) { toast('warning', '声音文件没加载出来'); end(); } });
    try { var pr = el.play(); if (pr && pr.catch) pr.catch(function () { end(); }); } catch (e) { end(); }
    rerender();
  }
  function hasBought(st, id) { id = Number(id); return !!M.paid[id] || onlineOf(st).bought && onlineOf(st).bought.indexOf(id) >= 0; }
  async function buyAndPlay(id) {
    var w = findWork(id); if (!w) return { ok: false };
    if (M.player.id === Number(id) && M.player.mode === 'full') { stopPlay(); rerender(); return { ok: true, stopped: true }; }
    if (!online()) { toast('warning', '服务器暂时连不上'); return { ok: false }; }
    if (M.busy['buy' + id]) return { ok: false };
    M.busy['buy' + id] = true; rerender();
    try {
      var g = identity(), st = ctx().readState();
      var r = await M.api.rpc('va_buy', { p_token: g.token, p_work_id: Number(id), p_agency_id: onlineOf(st).agencyId || null });
      if (!r || !r.ok) {
        if (r && r.reason === 'own') { toast('info', REASON.own); play(w, 'full'); return { ok: true, own: true }; }
        toast('warning', reasonText(r)); return { ok: false, reason: r && r.reason };
      }
      var price = Number(r.price) || Number(w.price) || 0;
      await ctx().save(function (s) {
        var c = C(), o = normOnline(s);
        if (c.addLedger) c.addLedger(s, 'onlineBuy', -price, noteOf('onlineBuy', { '社团': w.agency || '别家', '作品': w.title }), { mk: { work: Number(id), purchase: r.id } });
        if (c.bankerCheck) c.bankerCheck(s);   // 和签约一样：钱不够也能花，账上变负数就会有人来催
        if (o.bought.indexOf(Number(id)) < 0) { o.bought.push(Number(id)); if (o.bought.length > MK.boughtCap) o.bought = o.bought.slice(-MK.boughtCap); }
      });
      M.paid[Number(id)] = true;
      w.sales = (Number(w.sales) || 0) + 1;
      play(w, 'full');
      return { ok: true, price: price, purchase: r.id };
    } catch (e) { markOffline(e); toast('warning', '没付上：' + ((e && e.message) || e)); return { ok: false }; }
    finally { M.busy['buy' + id] = false; rerender(); }
  }
  async function rate(id, stars, comment) {
    stars = Math.round(Number(stars)); comment = cut(comment || '', MK.commentMax);
    var st = ctx().readState();
    if (!(stars >= 1 && stars <= 5)) return { ok: false, msg: '先点星星' };
    if (!hasBought(st, id)) return { ok: false, msg: REASON.not_bought };
    var chk = textCheck(comment, '评价'); if (!chk.ok) return { ok: false, msg: chk.reason };
    try {
      var r = await M.api.rpc('va_rate', { p_token: identity().token, p_work_id: Number(id), p_stars: stars, p_comment: comment, p_agency_id: onlineOf(st).agencyId || null });
      if (!r || !r.ok) return { ok: false, msg: reasonText(r) };
      return { ok: true };
    } catch (e) { markOffline(e); return { ok: false, msg: '没交上：' + ((e && e.message) || e) }; }
  }
  async function report(id, reason) {
    try {
      var r = await M.api.rpc('va_report', { p_token: identity().token, p_work_id: Number(id), p_reason: cut(reason || '', 60) });
      return r && r.ok ? { ok: true } : { ok: false, msg: reasonText(r) };
    } catch (e) { markOffline(e); return { ok: false, msg: '没交上：' + ((e && e.message) || e) }; }
  }

  // 收藏（只存这台设备、跨聊天：放全局变量）
  function favList() { var f = gvGet().fav; return Array.isArray(f) ? f : []; }
  function isFav(id) { return favList().some(function (x) { return Number(x.id) === Number(id); }); }
  function toggleFav(w) {
    var g = gvGet(), f = Array.isArray(g.fav) ? g.fav : [], id = Number(w.id);
    var i = f.findIndex(function (x) { return Number(x.id) === id; });
    if (i >= 0) f.splice(i, 1);
    else { f.push({ id: id, title: w.title, agency: w.agency, agency_id: w.agency_id, stage_name: w.stage_name, talent_id: w.talent_id, tier: w.tier, price: w.price, tags: w.tags || [], audio_path: w.audio_path, sales: w.sales, stars: w.stars, stars_n: w.stars_n }); if (f.length > MK.favCap) f = f.slice(-MK.favCap); }
    g.fav = f; gvSet(g);
    return i < 0;
  }

  // ═════════════════════════ 界面（HTML 字符串，shacho.js 塞进市场页）═════════════════════════
  var STAGE_ZH = { check: '检查中……', agency: '在服务器上登记事务所……', mix: '混音中', mp3: '压成 mp3……', ticket: '领上传票……', upload: '上传中……', publish: '登记作品……' };
  function statusChip() {
