      '<div class="mk-nums"><b>' + esc(money(w.price)) + '</b><span>/次</span><span class="sep">·</span><span>' + (w.period_sales != null ? esc(w.period_sales) + ' 次（总 ' + esc(w.sales) + '）' : '听了 ' + esc(w.sales || 0) + ' 次') + '</span></div>' +
