  function grid(rows, ranked) { return rows && rows.length ? '<div class="mk-grid">' + rows.map(function (w, i) { return card(w, ranked ? i + 1 : 0); }).join('') + '</div>' : ''; }
  function chips(list, cur, act) { return '<div class="mk-chips">' + list.map(function (x) { return '<button class="mk-c' + (cur === x[0] ? ' on' : '') + '" data-act="' + act + '" data-v="' + esc(x[0]) + '">' + esc(x[1]) + '</button>'; }).join('') + '</div>'; }
  function tierChips(cur, act) { return chips([['', '全部']].concat(TIERS.map(function (t) { return [t, t]; })), cur, act); }
  function waitOr(key, html, emptyTxt) {
