  function backBtn() { return '<button class="mk-back" data-act="mk-back">← 返回</button>'; }

  function viewHome() {
    var u = M.ui;
    if (!M.data.list && !M.busy.list && !M.err.list) setTimeout(loadList, 0);
    var h = '<div class="mk-search"><input class="mk-q" id="mk-q" maxlength="20" placeholder="搜作品名、社团、声优" value="' + esc(u.q) + '"><button class="sh-btn sm" data-act="mk-search">搜</button>' +
      (u.q || u.tag ? '<button class="sh-btn sm" data-act="mk-clear">清空</button>' : '') + '</div>';
    if (M.data.tags && M.data.tags.length) h += '<div class="mk-chips tags">' + M.data.tags.map(function (t) { return '<button class="mk-c' + (u.tag === t.tag ? ' on' : '') + '" data-act="mk-tagq" data-v="' + esc(t.tag) + '">#' + esc(t.tag) + '</button>'; }).join('') + '</div>';
    h += chips(SORTS, u.sort, 'mk-sort') + tierChips(u.tier, 'mk-tier');
    if (u.tag) h += '<div class="mk-sum">标签 #' + esc(u.tag) + '</div>';
    h += waitOr('list', grid(M.data.list), u.q || u.tag || u.tier ? '没找到这样的作品。' : '市场上还空着。录一部，第一个上架吧——全服第一部作品就是你的。');
    var pages = Math.ceil(M.data.total / MK.pageSize);
    if (pages > 1) h += '<div class="mk-pager"><button class="sh-btn sm" data-act="mk-page" data-v="-1"' + (u.page <= 0 ? ' disabled' : '') + '>上一页</button><span>' + (u.page + 1) + ' / ' + pages + '</span><button class="sh-btn sm" data-act="mk-page" data-v="1"' + (u.page >= pages - 1 ? ' disabled' : '') + '>下一页</button></div>';
    return h;
  }
  function viewRank() {
    var u = M.ui, k = rankKey(), rows = M.data.rank[k];
    if (!rows && !M.busy.rank && !M.err.rank) setTimeout(loadRank, 0);
    var h = chips([['works', '作品'], ['agencies', '事务所'], ['talents', '声优']], u.rank, 'mk-rankkind') + chips(PERIODS, u.period, 'mk-period');
