  // 点击：data-act 以 mk- 开头的都归这里。返回 true = 处理了
  function handleAct(act, el, panel) {
    if (!act || act.indexOf('mk-') !== 0) return false;
    var id = el && el.getAttribute ? el.getAttribute('data-id') : null, v = el && el.getAttribute ? el.getAttribute('data-v') : null, u = M.ui;
    function q(sel) { try { return (panel || (ctx().panel && ctx().panel())).querySelector(sel); } catch (e) { return null; } }
    function go(view) { if (u.view !== view) { u.back.push(u.view); if (u.back.length > 20) u.back.shift(); } u.view = view; }
    var st;
    switch (act) {
      case 'mk-toggle': setOff(!isOff()); stopPlay(); if (!isOff()) syncInbox(true); break;
      case 'mk-retry': M.offlineUntil = 0; M.err = {}; M.data.list = null; M.data.board = null; M.data.rank = {}; break;
      case 'mk-view': u.view = v; u.back = []; if (v === 'home') { /* 列表留着 */ } break;
      case 'mk-back': u.view = u.back.pop() || 'home'; break;
      case 'mk-sort': u.sort = v; u.page = 0; loadList(); break;
      case 'mk-tier': u.tier = v; u.page = 0; loadList(); break;
      case 'mk-tagq': u.tag = u.tag === v && u.view === 'home' ? '' : v; u.page = 0; u.view = 'home'; u.back = []; loadList(); break;
      case 'mk-search': var qi = q('#mk-q'); u.q = cut(qi ? qi.value : '', 20); u.page = 0; loadList(); break;
      case 'mk-clear': u.q = ''; u.tag = ''; u.page = 0; loadList(); break;
      case 'mk-page': u.page = Math.max(0, u.page + (Number(v) || 0)); loadList(); break;
      case 'mk-rankkind': u.rank = v; break;
      case 'mk-period': u.period = v; break;
      case 'mk-rtier': u.tier = v; break;
      case 'mk-work': if (el.getAttribute('data-close')) { u.modal = null; M.ui.up = null; } go('work'); M.data.work = null; loadWork(id); break;
      case 'mk-agency': go('agency'); M.data.agency = null; loadAgency(id); break;
      case 'mk-talent': go('talent'); M.data.talent = null; loadTalent(id); break;
      case 'mk-preview': var pw = findWork(id); if (pw) { if (M.player.id === Number(id) && M.player.mode === 'preview') stopPlay(); else play(pw, 'preview'); } break;
      case 'mk-buy': buyAndPlay(id); return true;
      case 'mk-fav': var fw = findWork(id); if (fw) toast('success', toggleFav(fw) ? '收藏了' : '取消收藏'); break;
      case 'mk-star': var r0 = u.rate[id] = u.rate[id] || {}; r0.stars = Number(v); var ci = q('#mk-cm-' + id); if (ci) r0.comment = ci.value; break;
      case 'mk-rate':
        var r1 = u.rate[id] = u.rate[id] || {}, cm = q('#mk-cm-' + id); if (cm) r1.comment = cm.value;
        r1.busy = true; r1.err = '';
        rate(id, r1.stars, r1.comment).then(function (res) { r1.busy = false; if (res.ok) { r1.done = true; loadWork(id); } else r1.err = res.msg; rerender(); });
        break;
      case 'mk-report': u.modal = { kind: 'report', id: id, reason: '' }; break;
      case 'mk-rreason': if (u.modal) u.modal.reason = v; break;
