    s.loan = { amount: o.amount, left: o.amount, months: o.months, paid: 0, rate: o.rate, day: s.day, asmrDeals: [] };
    addLedger(s, 'loan', o.amount, noteOf('loan', { '期': o.months, '息': pct(o.rate) }));
    return s.loan;
  }
  // 月底扣一期；扣完账上还是负数 = 逾期，记罚息。返回 { overdue } 给界面弹她的 toast
  function payLoanMonth(s) {
    var ln = s.loan; if (!ln) return null;
    var b = loanBill(ln);
    addLedger(s, 'loanPay', -(b.principal + b.interest), noteOf('loanPay', { '第': ln.paid + 1, '共': ln.months, '本': moneyText(b.principal), '息': moneyText(b.interest) }));
    ln.left = Math.max(0, ln.left - b.principal); ln.paid++;
    var overdue = false;
    if (Number(s.money) < 0) {
      var pen = Math.max(1, Math.round(Math.max(ln.left, b.principal) * (Number(E.overdueRate) || 0)));
      addLedger(s, 'overdue', -pen, noteOf('overdue'));
      overdue = true;
    }
    if (ln.left <= 0 || ln.paid >= ln.months) delete s.loan;
    return { overdue: overdue, bill: b };
  }
  function payOffLoan(s) {
    if (!s.loan || Number(s.money) < s.loan.left) return false;
    addLedger(s, 'loanOff', -s.loan.left, noteOf('loanOff'));
    delete s.loan;
    return true;
  }

  // ═══ 银行：祝简推销理财（台词和产品在 lists.js 的 banker.wealth，数字在 economy.wealth）═══
  // 存档 s.wealth = { n: 买过几单（流水号）, pitchDay: 她上次来推销是第几天, held: [手上的], done: [结过的] }
  //   每一单 { id, n, pid, name, risk, amount: 本金, day: 买入那天, due: 到期那天, endDay?, payout?, rate?, how?: win/loss/wipe/redeem }
  var WE = E.wealth || {};
  var WEALTH_DONE_CAP = 60;
  function wealthOf(s) {
    if (!s.wealth || typeof s.wealth !== 'object') s.wealth = {};
    var w = s.wealth;
    if (!Array.isArray(w.held)) w.held = [];
    if (!Array.isArray(w.done)) w.done = [];
    if (!(Number(w.n) >= 0)) w.n = 0;
    return w;
  }
  function wealthProducts() { return ((L.banker && L.banker.wealth && L.banker.wealth.products) || []); }
  function wealthProduct(pid) { var ps = wealthProducts(); for (var i = 0; i < ps.length; i++) if (ps[i].id === pid) return { p: ps[i], i: i }; return null; }
  function wealthHeldSum(s) { return ((s.wealth && s.wealth.held) || []).reduce(function (a, h) { return a + (Number(h.amount) || 0); }, 0); }
  // 第 dd 天收盘时手上压着的本金（排行榜按成本算市值，买理财不掉名次）
  function wealthHeldAt(s, dd) {
    var w = s.wealth || {};
    return ((w.held || []).concat(w.done || [])).filter(function (h) { return h.day <= dd && (h.endDay == null || h.endDay > dd); })
      .reduce(function (a, h) { return a + (Number(h.amount) || 0); }, 0);
  }
  // 这一单到期的总收益率：同一个聊天种子 + 同一单（产品、买入日、流水号）永远同一个数，读档不重掷
  function wealthRate(seed, h) {
    var pr = wealthProduct(h.pid), pi = pr ? pr.i : 0, risk = h.risk || (pr && pr.p.risk) || '稳';
    var R = (WE.returns || {})[risk];
    var u = hash01(seed || 1, 500 + pi, (Number(h.day) || 0) * 1000 + (Number(h.n) || 0));
    if (!R) return 0;
    if (Array.isArray(R)) return Number(R[0]) + u * (Number(R[1]) - Number(R[0]));
    if (u < (Number(R.wipe) || 0)) return -1;
    var v = hash01(seed || 1, 600 + pi, (Number(h.day) || 0) * 1000 + (Number(h.n) || 0)), win = R.win || [2, 4];
    return Number(win[0]) + v * (Number(win[1]) - Number(win[0]));
  }
  // 她来不来推销：账上 ≥ 门槛、没有贷款、离上次来够 every 天、今天催收员没来过
  function wealthDue(s) {
    var B = L.banker; if (!B || !B.wealth || !wealthProducts().length) return false;
    if (s.loan || !(Number(s.money) >= (Number(WE.threshold) || 500000))) return false;
    var w = s.wealth || {};
    if (w.pitchDay != null && s.day - Number(w.pitchDay) < (Number(WE.every) || 7)) return false;
    if (Number(s.bankerDay) === s.day) return false;
    return true;
  }
  function wealthCheck(s) {
    if (!wealthDue(s)) return null;
    var B = L.banker, W = B.wealth;
    var inv = { id: 'v' + Date.now().toString(36) + rndU32().toString(36), key: 'wealth@' + s.day, special: 'wealth', recvDay: s.day, day: s.day,
      by: B.name, kind: 'staff', talentId: null, text: B.name + '：' + pick(W.invites && W.invites.length ? W.invites : B.lines), where: W.where || B.where || '银行', what: W.what || '', status: 'pending' };
    s.invites.push(inv); wealthOf(s).pitchDay = s.day;
    return inv;
  }
  // 账本里那一栏要不要露出来
  function wealthVisible(s) { return !!(L.banker && L.banker.wealth) && (Number(s.money) >= (Number(WE.threshold) || 500000) || wealthHeldSum(s) > 0); }
  // 买入额的几个快捷档（账上的 10% / 25% / 50%，取整到千；低于起投额的不给）
  function wealthChips(money) {
    var min = Number(WE.minBuy) || 10000;
    return (WE.chips || [0.1, 0.25, 0.5]).map(function (f) { return { f: f, amount: Math.floor(Math.max(0, Number(money) || 0) * f / 1000) * 1000 }; })
      .filter(function (c) { return c.amount >= min; });
  }
  // 买一单。返回 { ok, err, h }
  function buyWealth(s, pid, amount) {
    var pr = wealthProduct(pid); if (!pr) return { ok: false, err: '先挑一款产品。' };
    amount = Math.round(Number(amount) || 0);
    var min = Number(WE.minBuy) || 10000;
    if (amount < min) return { ok: false, err: '起投 ' + moneyText(min) + '。' };
    if (amount > Number(s.money)) return { ok: false, err: '账上没这么多钱。' };
    var w = wealthOf(s); w.n++;
    var h = { id: 'h' + s.day + '_' + w.n, n: w.n, pid: pr.p.id, name: pr.p.name, risk: pr.p.risk, amount: amount, day: s.day, due: s.day + (Number(pr.p.days) || 1) };
    w.held.push(h);
    addLedger(s, 'wealthBuy', -amount, noteOf('wealthBuy', { '产品': pr.p.name, '天': pr.p.days }), { holdId: h.id });
    return { ok: true, h: h };
  }
  function wealthArchive(w, h) {
    w.held = w.held.filter(function (x) { return x.id !== h.id; });
    w.done.push(h);
    if (w.done.length > WEALTH_DONE_CAP) w.done = w.done.slice(-WEALTH_DONE_CAP);
  }
  // 提前赎回：本金扣 redeemFee 手续费，不算收益
  function redeemWealth(s, id) {
    var w = wealthOf(s), h = w.held.find(function (x) { return x.id === id; });
    if (!h) return null;
    var fee = Math.round(h.amount * (Number(WE.redeemFee) || 0)), payout = h.amount - fee;
    h.endDay = s.day; h.payout = payout; h.rate = -fee / h.amount; h.how = 'redeem';
    wealthArchive(w, h);
    addLedger(s, 'wealthRedeem', payout, noteOf('wealthRedeem', { '产品': h.name, '费': moneyText(fee) }), { holdId: h.id });
    return h;
  }
  // 到期结算（endDay 换日之后调）：s.day ≥ due 的全结掉。返回结掉的那几单
  function settleWealth(s) {
    var w = wealthOf(s), out = [];
    w.held.filter(function (h) { return s.day >= h.due; }).forEach(function (h) {
      var rate = wealthRate(s.seed, h), payout = Math.max(0, Math.round(h.amount * (1 + rate)));
      h.endDay = s.day; h.rate = rate; h.payout = payout;
      h.how = payout <= 0 ? 'wipe' : payout >= h.amount ? 'win' : 'loss';
      var diff = payout - h.amount;
      wealthArchive(w, h);
      addLedger(s, 'wealthEnd', payout, noteOf('wealthEnd', { '产品': h.name, '本': moneyText(h.amount), '盈亏': h.how === 'wipe' ? '归零' : (diff >= 0 ? '赚了 ' + moneyText(diff) : '亏了 ' + moneyText(-diff)) }), { holdId: h.id });
      out.push(h);
    });
    return out;
  }
  function wealthLine(how) { var S = (L.banker && L.banker.wealth && L.banker.wealth.settle) || {}; return String(S[how] || ''); }

  // ═══ 市场页：事务所排行榜（单机版）═══
  // ⚠️ 这是本地算的：聊天变量在玩家自己的浏览器里，谁都能改。联机榜开了以后，市值和营收必须在服务器上算（Supabase 那边按作品成交记录汇总），不能信客户端传上来的数。
  function hash01(seed, a, b) {   // 同一个种子、同一对 (a, b) 永远给同一个 [0,1)
    var h = (Number(seed) >>> 0) ^ Math.imul(a + 1, 0x9E3779B1) ^ Math.imul(b + 7, 0x85EBCA77);
    h = Math.imul(h ^ (h >>> 16), 0x7FEB352D); h = Math.imul(h ^ (h >>> 15), 0x846CA68B); h ^= h >>> 16;
    return (h >>> 0) / 4294967296;
  }
  function rivalCap(seed, i, day) {
    var r = (L.rivals || [])[i]; if (!r) return 0;
    var dr = Number((E.marketCap || {}).rivalDrift) || 0, v = Number(r.cap) || 0;
    for (var d = 2; d <= day; d++) v *= 1 + (hash01(seed, i, d) * 2 - 1) * dr;
    return Math.round(v);
  }
  function monthKey(day) { var d = dateOf(day); return d.getFullYear() * 12 + d.getMonth(); }
  function rivalRevenue(seed, i, day) {
    var r = (L.rivals || [])[i]; if (!r) return 0;
    var d = dateOf(day), frac = d.getDate() / new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();   // 本月到今天为止
    return Math.round((Number(r.revenue) || 0) * frac * (0.8 + hash01(seed, i + 100, monthKey(day)) * 0.4));
  }
  function playerRevenue(st, day) {
    var mk = monthKey(day);
    return (st.ledger || []).filter(function (e) { return (e.kind === 'payout' || e.kind === 'online') && e.day <= day && monthKey(e.day) === mk; }).reduce(function (a, e) { return a + e.amount; }, 0);
  }
  function playerCap(money, roster, revenue) {
    var M = E.marketCap || {};
    var worth = (roster || []).reduce(function (a, r) { return a + (Number(r.fee) || 0); }, 0) * 10000;
    return Math.round(money * (Number(M.cash) || 0) + worth * (Number(M.worthYears) || 0) + revenue * (Number(M.revenueMul) || 0));
  }
  // 返回今天的榜（按市值从高到低）；每行带 move = 比昨天上升了几名（正数上升）
  function marketBoard(st, agencyName) {
    var day = st.day, seed = st.seed || 1;
    function rows(dd, money) {
      var a = (L.rivals || []).map(function (r, i) { return { name: r.name, cap: rivalCap(seed, i, dd), revenue: rivalRevenue(seed, i, dd), talents: r.talents, hit: r.hit, me: false }; });
      var best = (st.works || []).filter(function (w) { return w.day <= dd; }).sort(function (x, y) { return y.payout - x.payout; })[0];
      var rev = playerRevenue(st, dd);
      a.push({ name: agencyName || '你的事务所', cap: playerCap(money + wealthHeldAt(st, dd), st.roster, rev), revenue: rev, talents: st.roster.length, hit: best ? '《' + best.title + '》' : '—', me: true });
      a.sort(function (x, y) { return y.cap - x.cap; });
      a.forEach(function (r, i) { r.rank = i + 1; });
      return a;
    }
    var todayMoves = (st.ledger || []).filter(function (e) { return e.day === day; }).reduce(function (a, e) { return a + e.amount; }, 0);
    var now = rows(day, st.money), prev = day > 1 ? rows(day - 1, st.money - todayMoves) : null;
    now.forEach(function (r) { var p = prev && prev.find(function (x) { return x.name === r.name && x.me === r.me; }); r.move = p ? p.rank - r.rank : 0; });
    return now;
  }

  // ═══ 起名过滤：事务所名 / 艺名 / 作品名和简介共用（表在 lists.js 的 nameBlock）═══
  // 洗名字：NFKC（全角转半角）→ 去声调 → 小写 → 只留字母和数字（空格、标点、符号、emoji、零宽字符全去掉）
  function nameNorm(s) {
    var t = String(s || '');
    try { t = t.normalize('NFKC').normalize('NFD').replace(/\p{M}/gu, '').normalize('NFC'); } catch (e) {}
    t = t.toLowerCase();
    try { t = t.replace(/[^\p{L}\p{N}]/gu, ''); } catch (e) { t = t.replace(/[\s​-‏⁠﻿!-\/:-@\[-`{-~　-〿＀-／：-＠［-｀｛-･]/g, ''); }
    return t;
  }
  function nameCheck(str) {
    var B = L.nameBlock || {}, words = B.words || [], latin = B.latin || [], allow = B.allow || [];
    var a = nameNorm(str);
    allow.forEach(function (w) { a = a.split(nameNorm(w)).join('_'); });   // 正经词先抠掉（留个占位，免得前后两个字拼成新词）
    var LEET = { '0': 'o', '1': 'i', '3': 'e', '4': 'a', '5': 's', '7': 't', '8': 'b' };
    // 数字夹在中间当分隔符的（鸡1巴、s1b）去掉数字再比一遍；数字冒充字母的（l0li）换回字母再比一遍
    var forms = [a, a.replace(/\d+/g, ''), a.replace(/[0134578]/g, function (d) { return LEET[d]; })];
    var hit = forms.some(function (f) {
      if (words.some(function (w) { var k = nameNorm(w); return k && f.indexOf(k) >= 0; })) return true;
      var runs = f.match(/[a-z]+/g) || [];
      return latin.some(function (w) {
        var exact = w.charAt(0) === '=', k = exact ? w.slice(1) : w;
        return runs.some(function (r) { return r === k || (!exact && k.length >= 4 && r.indexOf(k) >= 0); });
      });
    });
    if (!hit) return { ok: true, reason: '' };
    var rs = B.reasons && B.reasons.length ? B.reasons : ['这个名字工商局不给批哦～'];
    return { ok: false, reason: pick(rs) };
  }
  function stripHtml(s) {
    return String(s || '').replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/<(style|script)[\s\S]*?<\/\1>/gi, '').replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  }

  // ── 音效行（10-18）：[音效:钥匙] 放一下；[音效:停] 停掉垫着的循环 ──
  //   同一格里可以再带几样，空格隔开、顺序随意：×3（也认 x / * ）连放 3 遍；0-4s（也认 ~ ～ 到、秒）只放第 0~4 秒；叠 = 垫在后面几行人声底下，不等它放完
  //   例：[音效:拍手慢 0-6s 叠] [音效:亲吻×3] [音效:马鞭 ×2 叠]
  //   循环的（lists.js sfx 里 loop: true）一律垫着放，直到 [音效:停]；单次的默认放完再念下一句
  //   老写法 [音效] 椅子往后滑（没钥匙）：只显示，不放
  var SFX_LINE = /^\s*[\[［]\s*音效\s*[:：]?\s*([^\]］]*)[\]］]\s*(.*)$/;
  function parseSfx(t) {
    var m = String(t || '').match(SFX_LINE); if (!m) return null;
    var body = m[1].trim(), rest = m[2].trim();
    if (!body) return { key: '', note: rest };
    if (/^(停|stop)$/i.test(body)) return { stop: true, key: '', note: rest };
    var o = { key: '', times: 1, from: null, to: null, over: false, note: rest };
    body = body.replace(/[×xX*＊]\s*(\d{1,2})/, function (_, n) { o.times = Math.max(1, Math.min(20, Number(n) || 1)); return ' '; });
    body = body.replace(/(\d+(?:\.\d+)?)\s*(?:s|秒)?\s*[-~～—到]\s*(\d+(?:\.\d+)?)\s*(?:s|秒)?/i, function (_, a, b) {
      a = Number(a); b = Number(b); if (b > a && a >= 0) { o.from = a; o.to = b; } return ' ';
    });
    body = body.replace(/(^|\s)叠加?(?=\s|$)/, function () { o.over = true; return ' '; });
    o.key = body.trim().split(/\s+/)[0] || '';
    var def = (L.sfx || {})[o.key];
    o.loop = !!(def && def.loop);
    if (o.loop) { o.over = true; o.times = 1; }
    return o;
  }
  function secText(x) { return String(Math.round(Number(x) * 100) / 100); }
  // 选项 → 剧本里的写法（录音室小格子改完写回这一行，作品里存的就是这串）
  function sfxText(o) {
    if (!o) return '';
    if (o.stop) return '[音效:停]' + (o.note ? ' ' + o.note : '');
    if (!o.key) return '[音效]' + (o.note ? ' ' + o.note : '');
    var t = '[音效:' + o.key + (!o.loop && o.times > 1 ? '×' + o.times : '');
    if (o.from != null && o.to != null && o.to > o.from) t += ' ' + secText(o.from) + '-' + secText(o.to) + 's';
    if (o.over && !o.loop) t += ' 叠';
    return t + ']' + (o.note ? ' ' + o.note : '');
  }

  // ═══ 剧本：我们的剧本库 + 游戏里随机写剧本（10-18 加）═══
  // 剧本分两种（Fan 10-18）：① 我们写好、放服务器上的（剧本库）② 玩家拿我们的提示词在游戏里现写的（跟随机 NPC 一样：代码抽格子，AI 照写法写）
  // 现写的存在聊天变量 shacho.myScripts（最多 SG_CAP 份），跟这个聊天走
  var SG_CAP = 30;
  var SG_MINE = [];   // 当前聊天的 myScripts（normState 每次读档时更新）
  var SG_LIB = null;  // 服务器拉下来的剧本库；没拉到 = 用 lists.js 里的本地那份
  function setMyScripts(a) { SG_MINE = Array.isArray(a) ? a : []; }
  function setLibrary(a) { SG_LIB = (Array.isArray(a) && a.length) ? a : null; }
  function libraryList() { return SG_LIB || L.libraryScripts || []; }
  // 剧本选单分三组：我们的剧本库（含还没被替换的占位稿）/ 我写的（生成的）/ 试音稿。i = 在 allScripts() 里的序号
  function scriptGroups() {
    var all = allScripts(), nLib = libraryList().length + (L.studioScripts || []).length, nDemo = (L.scripts || []).length;
    var g = [{ key: 'lib', label: '我们的剧本库', items: [] }, { key: 'mine', label: '我写的', items: [] }, { key: 'demo', label: '试音稿', items: [] }];
    all.forEach(function (s, i) { g[i < nLib ? 0 : i < nLib + nDemo ? 2 : 1].items.push({ s: s, i: i }); });
    return g;
  }
  function scriptIndexOf(sid) { return allScripts().findIndex(function (x) { return scriptId(x) === sid; }); }
  function tiersUpTo(t) { return TIER_ORDER.slice(0, tierIdx(t) + 1); }

  // ── 抽格子（10-17 随机格子版）：档位 ≤ 她的尺度（want = 社长自己挑的档，超了不算）→ 共用的一堆格子各抽一条 + 这一档独有的格子 + 0~2 个音效 + 几行 ──
  //   格子故意不配套（跟抽签清单一样）：模型只管把抽到的每一样都写进去
  var SG_SLOTS = [   // [字段, 给玩家看的名字（弹层）, scriptGen 里的池子, 提示词里的短名（大括号里用）]
    ['type', '类型', '', '类型'], ['event', '今晚的事', 'events', '今晚'], ['scene', '场景', '', '场景'], ['who', '她是', '', '她是'], ['rel', '你们的关系', 'relations', '关系'],
    ['open', '开场', 'openings', '开场'], ['twist', '中间的意外', 'twists', '意外'], ['prop', '一定要出现的东西', 'props', '物件'], ['curve', '她的情绪', 'curves', '情绪'],
    ['end', '收尾', 'endings', '收尾'], ['tic', '她的口头小毛病', 'tics', '口癖'],
    ['step', '亲密到哪一步', '', '亲密'], ['rule', '这次的规矩', '', '规矩'], ['gear', '用到的道具', '', '道具'], ['reward', '奖励或惩罚', '', '奖惩'], ['safe', '安全词', '', '安全词'],
    ['play', '深渊玩法', '', '玩法'], ['means', '她的手段', '', '手段'], ['changed', '你被改掉了什么', '', '改掉了'], ['exit', '退路怎么没的', '', '退路'],
  ];
  var SG_TIER_KEYS = ['step', 'rule', 'gear', 'reward', 'safe', 'play', 'means', 'changed', 'exit'];
  // 带档位的条目：tierPools 里和共用格同名的池子，剧本档位 ≥ 那一档才并进来（R15 的条目全年龄抽不到，R15 往上都抽得到）
