  //   ⑤ 面板里随时能点「撤掉」手动清。
  var SCENE_ID = 'shacho-scene', OLD_INV_ID = 'shacho-invite';
  var GOT_MEM = null;   // MESSAGE_RECEIVED 的 got 先记在内存里：存档排队还没落账时，紧接着的 MESSAGE_SENT 也认得出来
  function personBlock(p) {
    var g = p.gen || {};
