  }
  function writeShMemo(lines) {
    if (!lines || !lines.length) return _memoQ;
    _memoQ = _memoQ.then(doWrite, doWrite);
    return _memoQ;
    async function doWrite() {
      try {
        var lastId = await getLastMessageId();
        if (lastId == null || lastId < 0) return;
        var msgs = await getChatMessages(Math.max(0, lastId - 5) + '-' + lastId);
        if (!msgs || !msgs.length) return;
        var m = msgs[msgs.length - 1];
        if (m.role === 'user') { for (var k = msgs.length - 2; k >= 0; k--) { if (msgs[k] && msgs[k].role === 'assistant') { m = msgs[k]; break; } } }
        var upd = memoMerge(m.message, lines);
        if (upd == null) return;
        await setChatMessages([{ message_id: m.message_id, message: upd }], { refresh: 'affected' });
