  // ═══ 录音室 ═══
  // 一场录音存在聊天变量 shacho.rec（同一时间只有一场，进棚时扣一次棚费）：
  //   { id, tid: 艺人id, sid: 剧本id, title, tier: 剧本档位, from: { kind: 'take', n: 从排练第几遍开始 } | { kind: 'script' }, day, cost,
  //     speed: 这场的语速（空 = 跟 ⚙）,
  //     lines: [{ id, text, rec: 录了几次（0 = 还没录；多出来的算重录）, mute: 整行不念（[停N] / [音效:x]）, speed: 这句单独的语速（空 = 跟这场）, spd: 上次录的时候用的语速 }] }
  // 改语速：那句的声音作废（▶ 会按新语速重新合成，不算重录）；点「重录」才算一次重录。音效行的选项（次数 / 截取 / 叠加）直接改写这一行的字（sfxText）
  // 声音只在内存：AUD.cache['行id#第几次']。刷新以后点 ▶ 会照这句重新合成，不算重录。
  // 「完成」→ 起名、写简介 →「上线」= 单机结算（联机市场开了以后这里改成真的上架）：
  //   ① 宣发打分：AI 读最近 20 条正文，只回 0~3 ② 代码算分、掷骰子、定档、算销量和钱 ③ AI 照结果写 S. 的报告 ④ 入账、存进 shacho.works
  var REC = { busy: {}, all: false };
  var WORK_CAP = 200;
  function stPerson(st) {
    st = st || readState();
    var p = st.roster.find(function (r) { return r.id === UI.st.tid; });
    if (!p && st.roster.length) { p = st.roster[0]; UI.st.tid = p.id; }
    return p || null;
  }
  function stScript() { var all = allScripts(); return all[Number(UI.st.sidx) || 0] || all[0]; }
  function lineSpeaks(t) { return ttsPlan(t).some(function (x) { return x.text; }); }
  function takesForScript(st, p, s) {
    var sid = scriptId(s), txt = scriptText(s, p);
    return takesOf(st, p.id).filter(function (t) { return t.script && (t.script.sid === sid || t.script.text === txt); });
  }
  // 从哪开始录：排练过这份 → 她最近那一遍；没排练过 → 剧本原文（{称呼} 换好）
  function recSource(st, p, s) {
    var tk = takesForScript(st, p, s), last = tk[tk.length - 1];
    if (last && last.read) return { from: { kind: 'take', n: last.n }, lines: String(last.read).split(/\s*[／\/\n]\s*/).map(function (x) { return x.trim(); }).filter(Boolean) };
    return { from: { kind: 'script' }, lines: (s.lines || []).map(function (l) { return fillTpl(l, p); }) };
  }
  function recPerson(st, sess) { return sess ? st.roster.find(function (r) { return r.id === sess.tid; }) || null : null; }
  function lineAid(l) { return l.id + '#' + (Number(l.rec) || 0); }
  async function startSession() {
    var st = readState(), p = stPerson(st), s = stScript();
    if (!p) { toast('warning', '旗下还没有艺人'); return; }
    if (!canRecord(p, s)) { toast('warning', (p.stageName || p.realName) + '：' + refuseLine(p)); return; }
    var src = recSource(st, p, s), cost = Number(E.sessionCost) || 0;
    var sid = 'r' + Date.now().toString(36) + rndU32().toString(36);
    var sess = { id: sid, tid: p.id, sid: scriptId(s), title: s.title, tier: s.tier || TIER_ORDER[0], from: src.from, day: st.day, cost: cost, speed: null,
      lines: src.lines.map(function (t, i) { return { id: sid + '-' + i, text: t, rec: 0, mute: !lineSpeaks(t), speed: null }; }) };
    stopAudio(); dropReady();
    await save(function (s2) {
      s2.rec = sess;
      if (cost) addLedger(s2, 'session', -cost, noteOf('session', { '艺名': p.stageName || p.realName, '剧本': s.title }), { talentId: p.id });
      bankerCheck(s2);
    });
    render();
    toast('info', (p.stageName || p.realName) + ' 进棚了' + (cost ? '，棚费 ' + moneyText(cost) : ''));
  }
  // 录一句（重录也走这里）：这句按 ttsPlan 拆好，一段一段合成完才算录上
  async function recLine(i, play) {
    var st = readState(), sess = st.rec; if (!sess) return false;
    var line = sess.lines[i]; if (!line || line.mute) return false;
    var p = recPerson(st, sess); if (!p) { toast('warning', '这场录音的艺人不在旗下了'); return false; }
    if (REC.busy[line.id]) return false;
    var spd = lineSpd(sess, line), plan = ttsPlan(line.text, spd), fishId = p.voice && p.voice.fishId;
    REC.busy[line.id] = 1; if (play) stopAudio(); render();
    try {
      for (var k = 0; k < plan.length; k++) if (plan[k].text) plan[k].url = await speakItem(plan[k], fishId);
    } catch (e) { delete REC.busy[line.id]; render(); toast('warning', '第 ' + (i + 1) + ' 句没录上：' + ((e && e.message) || e)); return false; }
    var n = (Number(line.rec) || 0) + 1, aid = line.id + '#' + n;
    AUD.cache[aid] = plan;
    await save(function (s) { if (s.rec && s.rec.id === sess.id && s.rec.lines[i]) { s.rec.lines[i].rec = n; s.rec.lines[i].spd = spd; } });
    delete REC.busy[line.id]; render();
    if (play) playSample(aid, line.text, fishId, spd);
