  }
  async function recAll() {
    if (REC.all) return;
    REC.all = true; stopAudio(); render();
    var sess = readState().rec, n = 0;
    if (sess) {
      for (var i = 0; i < sess.lines.length; i++) {
        var cur = readState().rec; if (!cur || cur.id !== sess.id) break;
        var l = cur.lines[i];
        if (l.mute || l.rec > 0) continue;
        if (!(await recLine(i, false))) break;
