  }
  function playLine(i) {
    var st = readState(), sess = st.rec; if (!sess) return;
    var l = sess.lines[i], p = recPerson(st, sess); if (!l || !p) return;
    playSample(lineAid(l), l.text, p.voice && p.voice.fishId, lineSpd(sess, l));
  }
  // 录音室的语速：这句自己调过 → 它；不然这场调过 → 这场；都没有 → ⚙ 的基础语速
  function lineSpd(sess, l) { return Number(l && l.speed) || Number(sess && sess.speed) || baseSpeed(); }
  // 改语速。i < 0 = 整场；d = 几格（一格 0.05）；d = 0 = 这句回到跟整场
  async function setRecSpeed(i, d) {
    var sess = readState().rec; if (!sess) return;
    var hit = [];
    if (i < 0) {
      var ns = clampSpd(lineSpd(sess, null) + d * 0.05);
      sess.lines.forEach(function (l) { if (!l.speed) hit.push(l); });
      await save(function (s) { if (s.rec && s.rec.id === sess.id) s.rec.speed = ns; });
    } else {
      var l = sess.lines[i]; if (!l || l.mute) return;
      var nl = d ? clampSpd(lineSpd(sess, l) + d * 0.05) : null;
      hit.push(l);
      await save(function (s) { if (s.rec && s.rec.id === sess.id && s.rec.lines[i]) s.rec.lines[i].speed = nl; });
    }
    hit.forEach(function (l) { var aid = lineAid(l); if (AUD.curId === aid) stopAudio(); delete AUD.cache[aid]; });   // 旧语速的声音作废
    render();
  }
  // 音效行的小格子：k = times / over / from / to；v = 新值
  async function setSfxOpt(i, k, v) {
    var sess = readState().rec; if (!sess || !sess.lines[i]) return;
    var o = parseSfx(sess.lines[i].text); if (!o || !o.key || o.stop) return;
    var len = Number(((L.sfx || {})[o.key] || {}).len) || 0;
    if (k === 'times') o.times = Math.max(1, Math.min(20, (Number(o.times) || 1) + Number(v)));
    else if (k === 'over') o.over = !o.over;
    else if (k === 'from' || k === 'to') {
      var x = String(v).trim() === '' ? null : Math.max(0, Number(v));
      if (x != null && len) x = Math.min(x, len);
      if (k === 'from') o.from = x; else o.to = x;
      if (o.from == null && o.to != null) o.from = 0;
      if (o.to == null && o.from != null) o.to = len || null;
      if (!(o.to > o.from)) { o.from = null; o.to = null; }
      if (o.from === 0 && len && o.to >= len) { o.from = null; o.to = null; }   // 等于整段 = 不截
    }
    var txt = sfxText(o);
    var aid = lineAid(sess.lines[i]) + ':sfx'; if (AUD.curId === aid) stopAudio(); delete AUD.cache[aid];
    await save(function (s) { if (s.rec && s.rec.id === sess.id && s.rec.lines[i]) s.rec.lines[i].text = txt; });
    render();
  }
  function playSfxLine(i) {
    var sess = readState().rec; if (!sess || !sess.lines[i]) return;
    var l = sess.lines[i]; playSample(lineAid(l) + ':sfx', l.text, '');
  }
  function recStats(sess) {
    var spk = sess.lines.filter(function (l) { return !l.mute; });
    return { lines: spk.length, recorded: spk.filter(function (l) { return l.rec > 0; }).length, retakes: spk.reduce(function (a, l) { return a + Math.max(0, (Number(l.rec) || 0) - 1); }, 0) };
  }
  async function abandonSession() { stopAudio(); await save(function (s) { delete s.rec; }); render(); }

  // ── 上线结算 ──
  async function recentChatText() {
    try {
      var last = Number(getLastMessageId());
      if (!(last >= 0)) return '';
      var msgs = await getChatMessages(Math.max(0, last - 19) + '-' + last, { hide_state: 'unhidden' });
      // m.message 是楼层正文；酒馆把推理单独存在 extra.reasoning，这里不读它。storyOnly 只洗这份拷贝，聊天记录本身不动
      var txt = (msgs || []).map(function (m) { return (m.name || m.role || '') + '：' + storyOnly(m.message).slice(0, 600); }).filter(function (x) { return x.length > 2; }).join('\n\n');
      return txt.length > 6000 ? txt.slice(-6000) : txt;
    } catch (e) { return ''; }
  }
  async function effortCheck(w) {
    var txt = await recentChatText();
    if (!txt.trim()) return { score: 0, note: '', skipped: true };
    var pr = buildEffortPrompt(w, txt);
    try {
      var raw = rawText(await genRaw({
        user_input: pr.user, should_silence: true, max_chat_history: 0,
        ordered_prompts: [{ role: 'system', content: SANDBOX_FICTION }, { role: 'system', content: pr.sys }],
        generation_id: 'shacho-eff-' + Date.now().toString(36),
      }));
      var r = parseEffort(raw);
      return { score: r.score, note: r.ok ? r.note : '', ok: r.ok };
    } catch (e) { return { score: 0, note: '', err: (e && e.message) || String(e) }; }
  }
  async function genReport(w) {
    var pr = buildReportPrompt(w);
    try {
      var raw = rawText(await genRaw({
        user_input: pr.user, should_silence: true, max_chat_history: 0,
        ordered_prompts: [{ role: 'system', content: SANDBOX_FICTION }, { role: 'system', content: pr.sys }],
        generation_id: 'shacho-rep-' + Date.now().toString(36),
      }));
      var lines = parseReport(raw);
      if (lines.length >= 2) return { lines: lines, ai: true };
    } catch (e) {}
    return { lines: fallbackReport(w), ai: false };
  }
  async function publishWork(title, blurb) {
    if (UI.settling) return;
    var st = readState(), sess = st.rec; if (!sess) { UI.modal = null; render(); return; }
    var p = recPerson(st, sess); if (!p) { UI.modal = null; render(); toast('warning', '这场录音的艺人不在旗下了'); return; }
    title = String(title || '').trim().replace(/\s+/g, ' ').slice(0, 30);
    blurb = String(blurb || '').trim().replace(/\s+/g, ' ').slice(0, 60);
    var nc = nameCheck(title), nb = nameCheck(blurb);
    var perr = !title ? '作品得有个名字' : !nc.ok ? nc.reason : !nb.ok ? '简介里有个词过不了审：' + nb.reason : '';
    if (perr) { UI.modal.err = perr; UI.modal.title = title; UI.modal.blurb = blurb; render(); return; }
    var s = allScripts().find(function (x) { return scriptId(x) === sess.sid; }) || { title: sess.title, tier: sess.tier, lines: [] };
    var tk = takesForScript(st, p, s), rs = recStats(sess);
    var inp = { rank: rankOf(p), fit: Math.max(0, tierIdx(p.tier) - tierIdx(sess.tier)), takes: tk.length, dirs: tk.filter(function (t) { return t.dir; }).length,
      retakes: rs.retakes, lines: rs.lines, recorded: rs.recorded };
    stopAudio(); if (EXP.ready && EXP.ready.id === 'sess') dropReady();
    UI.settling = true; UI.modal = { kind: 'settle', stage: 'effort', title: title }; render();
    var w = { title: title, blurb: blurb, agency: agencyName(st), stageName: p.stageName || p.realName, scriptTitle: s.title, scriptTier: sess.tier, skillLabel: (p.skill && p.skill.label) || '' };
    var eff = await effortCheck(w);
    inp.effort = eff.score;
    var res = scoreWork(inp), sale = salesFor(res.tier, sess.tier), why = scoreWhy(res, inp);
    Object.assign(w, { tier: res.tier, sales: sale.sales, price: sale.price, payout: sale.payout, why: why, roll: res.roll,
      effortNote: eff.score ? (eff.score + ' 分' + (eff.note ? '：' + eff.note : '')) : (eff.note || '') });
    UI.modal = { kind: 'settle', stage: 'report', title: title }; render();
    var rep = await genReport(w);
    var mul = Number((E.worthMul || {})[res.tier]) || 1, oldFee = Number(p.fee) || 0, newFee = Math.round(oldFee * mul * 10) / 10;
    var wid = 'w' + Date.now().toString(36) + rndU32().toString(36);
    var work = { id: wid, title: title, blurb: blurb, agency: w.agency, talentId: p.id, stageName: w.stageName, fishId: p.voice && p.voice.fishId,
      script: { sid: sess.sid, title: s.title, tier: sess.tier }, from: sess.from,
      lines: sess.lines.map(function (l) { return { text: l.text, aid: lineAid(l), mute: !!l.mute, speed: l.mute ? null : lineSpd(sess, l) }; }),
      tier: res.tier, tierIdx: res.tierIdx, score: { inp: inp, res: res, why: why }, sales: sale.sales, price: sale.price, payout: sale.payout,
      effort: eff, report: rep.lines, reportAi: rep.ai, fee: [oldFee, newFee], day: st.day, at: Date.now() };
    await save(function (s2) {
      s2.works.push(work); if (s2.works.length > WORK_CAP) s2.works = s2.works.slice(-WORK_CAP);
      addLedger(s2, 'payout', sale.payout, noteOf('payout', { '作品': title, '次': sale.sales }), { workId: wid });
      var r = s2.roster.find(function (x) { return x.id === p.id; }); if (r) r.fee = newFee;
      addNews(s2, w.stageName + '的《' + title + '》上线「' + res.tier + '」入账' + moneyText(sale.payout));
      delete s2.rec;
    });
    UI.settling = false; UI.modal = { kind: 'settle', stage: 'done', workId: wid }; render();
  }
  // 企划页：整部连着放（各句的声音和录音室共用缓存，录过的直接放）
  function playWork(id) {
    var w = readState().works.find(function (x) { return x.id === id; }); if (!w) return;
    var aid = w.id + ':all';
    if (AUD.curId !== aid) {
      var plan = [];
      w.lines.forEach(function (l) { plan = plan.concat(AUD.cache[l.aid] || (AUD.cache[l.aid] = ttsPlan(l.text, l.speed))); });   // 每句按录的时候的语速；音效行跟着放
      if (!plan.some(function (x) { return x.text; })) { toast('warning', '这部没有能念的字'); return; }
