  FAB.innerHTML = '<span class="t">社长室</span><span class="s">PRESIDENT</span>';
  DOC.body.appendChild(FAB);

  var PANEL = DOC.createElement('div');
  PANEL.id = 'shacho-panel'; PANEL.setAttribute('data-swipe-ignore', 'true');
  DOC.body.appendChild(PANEL);
  // 手势隔离：触摸事件不往酒馆冒泡（酒馆在 document 上听滑动去切回复/开抽屉；TOY·LINK 吃过误触退出的亏）。
  // 只拦冒泡、不 preventDefault，面板里照常滚动。面板只有 ✕ 能关。
  ['touchstart', 'touchmove', 'touchend', 'touchcancel'].forEach(function (t) { PANEL.addEventListener(t, function (e) { e.stopPropagation(); }, { passive: true }); });

  // ── 立绘 <img>：加载失败 → 拿掉图、记下这个地址（之后重绘不再试），露出底下的斜纹 + 姓 ──
  // error 不冒泡，只能在捕获阶段听；不用行内 onerror，免得撞上酒馆的 CSP
  var PIC_BAD = {};
  function portraitImg(n) {
    var u = portraitUrl(n);
    return (u && !PIC_BAD[u]) ? '<img class="sh-pic" src="' + esc(u) + '" alt="" loading="lazy" decoding="async" draggable="false">' : '';
  }
  PANEL.addEventListener('error', function (e) {
    var t = e.target; if (!t || t.tagName !== 'IMG' || !t.classList.contains('sh-pic')) return;
    PIC_BAD[t.getAttribute('src')] = 1;
    var box = t.parentNode; if (box && box.classList) box.classList.remove('has-img');
    t.remove();
  }, true);

  var TABS = [
    { id: 'calendar', zh: '日历', en: 'CALENDAR' },
    { id: 'audition', zh: '面试', en: 'AUDITION' },
    { id: 'rehearsal', zh: '排练室', en: 'REHEARSAL' },
    { id: 'studio', zh: '录音室', en: 'REC' },
    { id: 'talent', zh: '旗下艺人', en: 'TALENT' },
    { id: 'project', zh: '企划', en: 'PROJECT' },
    { id: 'market', zh: '市场', en: 'MARKET' },
    { id: 'schat', zh: 'S.', en: 'ASSISTANT' },   // 10-18：和社长助理说话
  ];
  var TIER_CLASS = { '全年龄': 't0', 'R15': 't1', 'R18 常见XP': 't2', 'R18 BDSM': 't3', '深渊': 't4' };
  function tierTag(t) { return '<span class="sh-tier ' + (TIER_CLASS[t] || 't1') + '">' + esc(t) + '</span>'; }
  function stars(n) { n = Math.max(1, Math.min(5, Number(n) || 1)); return '<span class="sh-stars">' + '★★★★★'.slice(0, n) + '<span style="opacity:.25">' + '★★★★★'.slice(0, 5 - n) + '</span></span>'; }

  function playBtn(id) {
    var on = AUD.curId === id, busy = !!AUD.busy[id];
    return '<button class="sh-play' + (on ? ' on' : '') + '" data-act="play" data-id="' + esc(id) + '"' + (busy ? ' disabled' : '') + ' aria-label="试听">' + (busy ? '…' : (on ? '■' : '▶')) + '</button>';
  }

  function renderHead(st) {
    // 顶栏：电脑「社长室 + 事务所名」；手机只放事务所名（窄）。账上余额一直看得见，点开是账本；负数变红
    var an = agencyName(st), neg = st.money < 0;
    return '<div class="sh-head"><div class="sh-logo' + (an ? ' has-ag' : '') + '"><span class="lg">社长室</span>' + (an ? '<small class="ag">' + esc(an) + '</small>' : '<small>PRESIDENT\'S OFFICE</small>') + '</div>' +
      '<div class="sh-meta">第 ' + st.day + ' 天<span class="full"> · 旗下 ' + st.roster.length + ' 人</span></div>' +
      (st.agency ? '<button class="sh-money' + (neg ? ' neg' : '') + '" data-act="ledger" title="账本"><span class="full">账上 ' + esc(moneyText(st.money)) + '</span><span class="cmp">' + esc(moneyShort(st.money)) + '</span></button>' : '') +
      '<button class="sh-ibtn" data-act="settings" title="设置">⚙</button>' +
      '<button class="sh-ibtn" data-act="night" title="夜间/白天">' + (PANEL.classList.contains('night') ? '☀' : '☾') + '</button>' +
      '<button class="sh-ibtn sh-close" data-act="close" title="关闭">✕</button></div>';
  }
  function renderNav() {
    return '<nav class="sh-nav">' + TABS.map(function (t) {
      return '<button class="sh-tab' + (UI.tab === t.id ? ' on' : '') + '" data-tab="' + t.id + '"><b>' + t.zh + '</b><i>' + t.en + '</i></button>';
    }).join('') + '</nav>';
  }

  function candCard(c, i) {
    var pic = portraitImg(c.portrait);   // 有立绘就盖在斜纹上；没有 / 加载失败照旧显示姓 + NO PHOTO
    var head = '<div class="sh-photo' + (pic ? ' has-img' : '') + '"><span class="ch">' + esc(c.surname) + '</span>' + pic + '<span class="no">No.' + String(i + 1).padStart(2, '0') + '</span><span class="tag">NO PHOTO</span></div>';
    if (c.status === 'loading') {
      return '<article class="sh-talent" data-id="' + esc(c.id) + '">' + head + '<div class="sh-tb"><h3 class="sh-name"><span class="rb">NEWCOMER</span>' + esc(c.surname) + ' ……</h3>' +
        '<div class="sh-skel" style="width:70%"></div><div class="sh-skel"></div><div class="sh-skel" style="width:85%"></div><div class="sh-wait">她在门外调整呼吸……</div></div></article>';
    }
    if (c.status === 'error') {
      return '<article class="sh-talent" data-id="' + esc(c.id) + '">' + head + '<div class="sh-tb"><h3 class="sh-name"><span class="rb">NEWCOMER</span>' + esc(c.surname) + ' ……</h3>' +
        '<div class="sh-errt">没准备好：' + esc(c.err || '') + '</div><div class="sh-acts"><button class="sh-btn pri" data-act="retry" data-id="' + esc(c.id) + '">再试一次</button><button class="sh-btn" data-act="pass" data-id="' + esc(c.id) + '">不等了</button></div></div></article>';
    }
    var g = c.gen || {};
    var rows = [
      ['年龄', c.age + ' 岁'], ['出身', esc(c.hometown)], ['声线', esc(c.voice.label)], ['专长', esc(c.specialty)],
      ['业务水平', stars(c.skill.rank) + esc(c.skill.label)], ['尺度', tierTag(c.tier)], ['身价', esc(feeText(c.fee))],
    ];
    if (c.quirk) rows.push(['怪癖', esc(c.quirk)]);
    if (c.facts && c.facts.length) rows.push(['备注', esc(c.facts.join('；'))]);
    return '<article class="sh-talent" data-id="' + esc(c.id) + '">' + head + '<div class="sh-tb">' +
      '<h3 class="sh-name"><span class="rb">NEWCOMER · 本名</span>' + esc(realName(c)) + '</h3>' +
      '<div class="sh-prof">' + rows.map(function (r) { return '<div class="r"><span class="k">' + r[0] + '</span><span class="v">' + r[1] + '</span></div>'; }).join('') + '</div>' +
      '<p class="sh-intro">' + esc(g.intro) + '</p>' +
      '<div class="sh-sample">' + playBtn(c.id) + '<div><b>VOICE SAMPLE</b><span>试音 ·「' + esc(CUR && CUR.script ? CUR.script.title : '') + '」</span></div></div>' +
      '<details class="sh-more"><summary>试音文本 / 档案底稿</summary>' +
        '<p><b>试音：</b>' + esc(g.demo) + '</p>' +
        '<p><b>反差：</b>' + esc(g.contrast) + '</p><p><b>死结：</b>' + esc(g.knot) + '</p><p><b>提醒：</b>' + esc(g.guard) + '</p>' +
        '<p><b>三色：</b>' + esc(c.base) + ' ／ ' + esc(c.main) + ' ／ ' + esc(c.accent) + '</p>' +
        '<p><b>抽到的：</b>' + esc([c.look, c.item, c.event, c.family, c.motive, c.ending, '叫你「' + c.callYou + '」，' + c.switchCond + '改口'].join('；')) + '</p>' +
      '</details>' +
      '<div class="sh-acts"><button class="sh-btn pri" data-act="sign" data-id="' + esc(c.id) + '">签约</button>' +
      '<button class="sh-btn" data-act="pass" data-id="' + esc(c.id) + '">不签</button>' +
      '<button class="sh-btn wide" data-act="invite" data-id="' + esc(c.id) + '">请她进来聊聊</button></div>' +
      '</div></article>';
  }

  function renderAudition() {
    var h = '<div class="sh-eyebrow">AUDITION</div><h2 class="sh-h">今天来面试的人</h2>';
    h += '<div class="sh-scriptbox"><div class="sh-label">① 挑一份试音稿，三个人念同一份</div><div class="sh-chips">' +
      L.scripts.map(function (s, i) { return '<button class="sh-chip' + (!UI.useCustom && UI.scriptIdx === i ? ' on' : '') + '" data-script="' + i + '">' + esc(s.title) + '</button>'; }).join('') +
      '<button class="sh-chip' + (UI.useCustom ? ' on' : '') + '" data-script="custom">自己写</button></div>';
    if (UI.useCustom) {
      h += '<div class="sh-custom">' + [0, 1, 2].map(function (i) { return '<input data-custom="' + i + '" maxlength="60" placeholder="第 ' + (i + 1) + ' 句" value="' + esc(UI.custom[i]) + '">'; }).join('') + '</div>';
    } else {
      var s = L.scripts[UI.scriptIdx] || L.scripts[0];
      h += '<div class="sh-lines">' + s.lines.map(function (l) { return '<div>' + esc(l) + '</div>'; }).join('') + '</div>';
    }
    h += '<div class="sh-go"><button class="sh-btn pri big" data-act="start"' + (UI.busy ? ' disabled' : '') + '>' + (UI.busy ? '她们在准备……' : (CUR && CUR.cands.length ? '换一批，重新面试' : '开始面试')) + '</button>' +
      '<small>② 三位新人各念一遍，比着听，签或不签</small></div></div>';
    if (CUR && CUR.cands.length) h += '<div class="sh-grid">' + CUR.cands.map(candCard).join('') + '</div>';
    else if (CUR) h += '<div class="sh-empty">这一批都看完了。想再见几个人，就点上面的「开始面试」。</div>';
    return h;
  }
  function renderTalent(st) {
    var h = '<div class="sh-eyebrow">TALENT</div><h2 class="sh-h">旗下艺人</h2>';
    if (!st.roster.length) return h + '<div class="sh-empty">还没有签下任何人。去「面试」见见新人吧。</div>';
    h += '<div class="sh-roster">' + st.roster.map(function (r) {
      return '<div class="sh-row"><div class="ph"><span>' + esc((r.stageName || '?').slice(0, 1)) + '</span>' + portraitImg(r.portrait) + '</div>' +
        '<div><div class="nm">' + esc(r.stageName) + '</div><div class="rn">本名 ' + esc(r.realName) + ' · ' + esc(r.age) + ' 岁' + tierTag(r.tier) + '</div>' +
        '<div class="rn">' + esc(r.voice && r.voice.label) + ' · 第 ' + esc(r.signedDay) + ' 天签约</div>' +
        '<div class="rn">身价 ' + esc(feeText(r.fee)) + ' · 月薪 ' + esc(moneyText(talentMonthly(r))) + (r.quirk ? ' · ' + esc(r.quirk) : '') + '</div></div>' +
        '<div class="rt">' + playBtn(r.id) + '<button class="sh-btn" data-act="to-rh" data-id="' + esc(r.id) + '">排练</button><button class="sh-btn" data-act="to-st" data-id="' + esc(r.id) + '">录音</button><button class="sh-btn" data-act="invite-r" data-id="' + esc(r.id) + '">叫她来</button></div></div>';
    }).join('') + '</div>';
    return h;
  }

  // 正文那边还挂着的一场（有就显示，能手动撤）
  // 顶上那条提示用戏里的话说（Fan 10-18：「正文待演」太出戏）
  function sceneLine(sc) {
    var n = '<b>' + esc(sc.name) + '</b>';
    if (sc.kind === 'rehearsal') return n + ' 在排练室等你';
    if (sc.kind === 'date') return '约了 ' + n + (sc.where ? ' · ' + esc(sc.where) : '');
    return n + ' 在门口等着';
  }
  function sceneBar(st) {
    var sc = st.scene; if (!sc) return '';
    return '<div class="sh-scene"><span>' + sceneLine(sc) + '</span>' +
      '<button class="sh-link" data-act="scene-clear">改天吧</button></div>';
  }

  // ── 日历 ──
  var INV_ST = { pending: '待回复', accepted: '已接受', ignored: '已忽略', went: '去过了', missed: '没回' };
  function invCard(v, st, sel) {
    var today = st.day;
    var when = [];
    if (v.day !== sel) when.push('约在 ' + mdText(v.day));
    if (v.recvDay !== sel) when.push(mdText(v.recvDay) + ' 收到');
    var acts = '';
    if (v.status === 'pending' && v.day >= today) {
      acts = '<button class="sh-btn pri" data-act="inv-accept" data-id="' + esc(v.id) + '">接受</button>' +
        (v.day === today ? '<button class="sh-btn" data-act="inv-go" data-id="' + esc(v.id) + '">现在就去</button>' : '') +
        '<button class="sh-btn" data-act="inv-ignore" data-id="' + esc(v.id) + '">忽略</button>';
    } else if (v.status === 'accepted' && v.day === today) {
      acts = '<button class="sh-btn pri" data-act="inv-go" data-id="' + esc(v.id) + '">现在就去</button>';
    }
    return '<div class="sh-inv s-' + esc(v.status) + '" data-inv="' + esc(v.id) + '"><div class="top"><b>' + esc(v.by) + '</b>' +
      (when.length ? '<span class="when">' + esc(when.join(' · ')) + '</span>' : '') +
      '<span class="st ' + esc(v.status) + '">' + esc(INV_ST[v.status] || v.status) + '</span></div>' +
      '<p>' + esc(v.text) + '</p><div class="wh">地点：' + esc(v.where) + '</div>' +
      (v.status === 'ignored' ? '<div class="owl">' + (v.sDeclined ? 'S. 替你推掉了' : '小鸮记下了') + '</div>' : '') +
      (acts ? '<div class="acts">' + acts + '</div>' : '') + '</div>';
  }
  function renderCalendar(st) {
    var today = st.day, sel = UI.calSel || today;
    var h = '<div class="sh-eyebrow">CALENDAR</div><h2 class="sh-h">日历</h2>' + sceneBar(st);
    h += '<div class="sh-today"><span class="d"><b>第 ' + today + ' 天</b>' + esc(mdText(today)) + '</span>' +
      '<button class="sh-btn pri" data-act="endday">结束今天</button></div>';
    // 月历（周一开头）
    var td = dateOf(today), vm = new Date(td.getFullYear(), td.getMonth() + UI.calOff, 1);
    var lead = (vm.getDay() + 6) % 7, dim = new Date(vm.getFullYear(), vm.getMonth() + 1, 0).getDate();
    var byDay = {};
    st.invites.forEach(function (v) { if (v.status === 'accepted' || v.status === 'went' || (v.status === 'pending' && v.day >= today)) (byDay[v.day] = byDay[v.day] || []).push(v); });
    var g = '<div class="sh-month"><div class="sh-mhead"><button class="sh-ibtn" data-act="cal-prev" title="上个月">◀</button><b>' + vm.getFullYear() + ' 年 ' + (vm.getMonth() + 1) + ' 月</b>' +
      '<button class="sh-ibtn" data-act="cal-next" title="下个月">▶</button></div><div class="sh-mgrid">' +
      ['一', '二', '三', '四', '五', '六', '日'].map(function (w) { return '<div class="sh-wd">' + w + '</div>'; }).join('');
    for (var i = 0; i < lead; i++) g += '<div></div>';
    for (var d = 1; d <= dim; d++) {
      var gd = dayOfDate(new Date(vm.getFullYear(), vm.getMonth(), d));
      if (gd < 1) { g += '<div class="sh-cd pre">' + d + '</div>'; continue; }
      var cls = 'sh-cd' + (gd === today ? ' today' : gd < today ? ' past' : ' future') + (gd === sel ? ' sel' : '');
      var dots = (byDay[gd] || []).slice(0, 4).map(function (v) { return '<i class="' + (v.status === 'pending' ? 'p' : v.status === 'went' ? 'w' : 'a') + '"></i>'; }).join('') +
        (st.notes.some(function (n) { return n.day === gd; }) ? '<i class="n"></i>' : '');
      g += '<button class="' + cls + '" data-day="' + gd + '"><span>' + d + '</span><span class="dots">' + dots + '</span></button>';
    }
    g += '</div><div class="sh-legend"><span><i></i>已接受</span><span><i class="p"></i>待回复</span><span><i class="w"></i>去过了</span>' + (st.notes.length ? '<span><i class="n"></i>S. 的备忘</span>' : '') + '</div></div>';
    // 选中那天的单子：约在这天的 + 这天收到的
    var list = st.invites.filter(function (v) { return v.day === sel || v.recvDay === sel; });
    var dh = '<div class="sh-dayh">' + (sel === today ? '今天' : '第 ' + sel + ' 天') + '<small>' + esc(mdText(sel)) + '</small></div>';
    var notes = st.notes.filter(function (n) { return n.day === sel; });
    var noteH = notes.map(function (n) { return '<div class="sh-note"><b>S. 的备忘</b><span>' + esc(n.text) + '</span><button class="sh-link" data-act="note-del" data-id="' + esc(n.id) + '">划掉</button></div>'; }).join('');
    var body = list.length ? noteH + '<div class="sh-invs">' + list.map(function (v) { return invCard(v, st, sel); }).join('') + '</div>'
      : notes.length ? noteH : '<div class="sh-empty">' + (sel === today ? '今天还没有人约你。' : sel < today ? '这天没什么事。' : '这天还没排东西。') + '</div>';
    return h + '<div class="sh-cal">' + g + '<div>' + dh + body + '</div></div>';
  }

  // ── 排练室 ──
  function takePlay(t) {
    var on = AUD.curId === t.id, busy = !!AUD.busy[t.id];
    return '<button class="sh-play' + (on ? ' on' : '') + '" data-act="play-take" data-id="' + esc(t.id) + '"' + (busy ? ' disabled' : '') + ' aria-label="播放">' + (busy ? '…' : (on ? '■' : '▶')) + '</button>';
  }
  function renderRehearsal(st) {
    var h = '<div class="sh-eyebrow">REHEARSAL</div><h2 class="sh-h">排练室</h2>' + sceneBar(st);
    if (!st.roster.length) return h + '<div class="sh-empty">旗下还没有艺人。先去「面试」签一个人，再带她来排练室。</div>';
    var p = rhPerson(st), R = UI.rh;
    var takes = takesOf(st, p.id);
    var left = '<div class="sh-box"><div class="sh-label">① 叫谁来排</div><div class="sh-chips">' +
      st.roster.map(function (r) { return '<button class="sh-chip' + (r.id === p.id ? ' on' : '') + '" data-rh-who="' + esc(r.id) + '">' + esc(r.stageName || r.realName) + '</button>'; }).join('') + '</div>' +
      '<div class="sh-hint">' + esc(p.realName) + ' · ' + esc(p.voice && p.voice.label) + ' · ' + esc(p.skill && p.skill.label) + '</div></div>';
    left += '<div class="sh-box"><div class="sh-label">② 剧本</div>' + scriptPicker(p, 'rh') + '<div class="sh-chips">' +
      '<button class="sh-chip' + (R.mode === 'custom' ? ' on' : '') + '" data-rh-mode="custom">自己写</button>' +
      '<button class="sh-chip' + (R.mode === 'paste' ? ' on' : '') + '" data-rh-mode="paste">贴剧本</button></div>';
    if (R.mode === 'custom') left += '<textarea data-rh-input="custom" maxlength="300" placeholder="写几句给她念，一行一句，300 字以内">' + esc(R.custom) + '</textarea>';
    else if (R.mode === 'paste') left += '<textarea class="long" data-rh-input="paste" maxlength="2000" placeholder="整段剧本贴进来（2000 字以内）。越长，她念得越久，Fish 合成也越久。">' + esc(R.paste) + '</textarea>';
    else {
      var s = allScripts()[Number(R.mode) || 0] || allScripts()[0];
      left += scriptMeta(s);
      left += '<div class="sh-lines">' + s.lines.map(function (l) { return '<div>' + cueHtml(fillTpl(l, p)) + '</div>'; }).join('') + '</div>';
      if (!canRecord(p, s)) left += '<div class="sh-refuse">🔒 ' + esc(p.stageName || p.realName) + '：「' + esc(refuseLine(p)) + '」</div>';
    }
    left += '</div>';
    left += '<div class="sh-box"><div class="sh-label">③ ' + (takes.length ? '给一句指导，她照着再来一遍' : '先听她念一遍') + '</div>';
    if (takes.length) {
      left += '<div class="sh-chips">' + (L.directions || []).map(function (d) { return '<button class="sh-chip' + (R.chips[d] ? ' on' : '') + '" data-rh-chip="' + esc(d) + '">' + esc(d) + '</button>'; }).join('') + '</div>' +
        '<input class="sh-in" data-rh-input="dir" maxlength="80" placeholder="或者自己说一句，比如：第二句慢一点，像刚睡醒" value="' + esc(R.dir) + '">';
    }
    left += '<div class="sh-rhgo">' +
      (takes.length ? '<button class="sh-btn pri" data-act="rh-again"' + (R.busy ? ' disabled' : '') + '>' + (R.busy ? '她在念……' : '给指导，再来一遍') + '</button>' +
        '<button class="sh-btn" data-act="rh-take"' + (R.busy ? ' disabled' : '') + '>从头念一遍</button>'
        : '<button class="sh-btn pri big" data-act="rh-take"' + (R.busy ? ' disabled' : '') + '>' + (R.busy ? '她在念……' : '听她念') + '</button>') +
      '<button class="sh-btn" data-act="rh-chat">去正文排</button></div>' +
      '<div class="sh-hint">每一遍 = 一次 AI 生成 + 一段 Fish 语音。「去正文排」把这场带进正文，当面排。</div></div>';
    var right = '<div class="sh-dayh">她念过的<small>' + (takes.length ? '共 ' + takes.length + ' 遍，最多留 ' + RH_CAP + ' 遍' : '还没有') + '</small></div>';
