  // ── 录音室 ──
  function sfxLabel(o) {   // 音效行的小标签：音效 · 拍手慢 · ×3 · 0–4 秒 · 叠
    if (o.stop) return '音效 · 停';
    if (!o.key) return '音效';
    var x = ['音效', o.key];
    if (!o.loop && o.times > 1) x.push('×' + o.times);
    if (o.from != null && o.to != null) x.push(secText(o.from) + '–' + secText(o.to) + ' 秒');
    if (o.loop) x.push('循环'); else if (o.over) x.push('叠');
    return x.join(' · ');
  }
  function cueHtml(t) {   // 行首的 [提示] 画成小标签；整行不念的画成灰字
    var sx = parseSfx(t); if (sx) return '<i class="cue sfx">' + esc(sfxLabel(sx)) + '</i>' + esc(sx.note || '');
    var s = String(t || ''), m, tags = [];
    while ((m = s.match(/^\s*[\[［]([^\]］]{1,12})[\]］]\s*/))) { tags.push(m[1]); s = s.slice(m[0].length); }
    return tags.map(function (x) { return '<i class="cue">' + esc(x.replace(/^音效[:：]?/, '音效 · ').replace(/^停\s*(\d+(?:\.\d+)?)$/, '停 $1 秒')) + '</i>'; }).join('') + esc(s);
  }
  function spdText(x) { return (Math.round(Number(x) * 100) / 100).toFixed(2) + '×'; }
  // 语速小格子：− 0.80× +；单句调过的，点中间的数回到跟整场
  function spdCtl(i, v, own) {
    return '<button class="sh-mini" data-act="rec-spd" data-i="' + i + '" data-d="-1"' + (v <= SPEED_MIN + 0.001 ? ' disabled' : '') + ' aria-label="慢一点">−</button>' +
      (own ? '<button class="sh-sv own" data-act="rec-spd" data-i="' + i + '" data-d="0" title="这句单独调过；点一下回到跟整场">' + spdText(v) + '</button>' : '<b class="sh-sv">' + spdText(v) + '</b>') +
      '<button class="sh-mini" data-act="rec-spd" data-i="' + i + '" data-d="1"' + (v >= SPEED_MAX - 0.001 ? ' disabled' : '') + ' aria-label="快一点">+</button>';
  }
  // 录音室里的音效行：次数 / 截取秒数 / 叠加 三个小格子 + ▶ 试听（改完写回这一行的字，跟作品一起存）
  function sfxRow(l, i, o) {
    var def = (L.sfx || {})[o.key], aid = lineAid(l) + ':sfx', on = AUD.curId === aid, pb = !!AUD.busy[aid];
    var len = def ? Number(def.len) || 0 : 0;
    var h = '<div class="sh-rl mute sfx"><span class="no">' + String(i + 1).padStart(2, '0') + '</span>' +
      '<div class="tx">' + cueHtml(l.text) + (def ? '<span class="cnt">' + (def.loop ? '循环，垫在后面几行底下，到「音效 · 停」为止' : '单次 ' + secText(len) + ' 秒') + '</span>' : '<span class="cnt">音效清单里没有这个钥匙，放不出来</span>') + '</div>';
    if (!def) return h + '</div>';
    h += '<div class="ops sfxops">';
    if (!def.loop) h += '<span class="sh-opt"><i>次数</i><button class="sh-mini" data-act="sfx-opt" data-k="times" data-v="-1" data-i="' + i + '"' + (o.times <= 1 ? ' disabled' : '') + ' aria-label="少一次">−</button><b class="sh-sv">×' + o.times + '</b><button class="sh-mini" data-act="sfx-opt" data-k="times" data-v="1" data-i="' + i + '"' + (o.times >= 20 ? ' disabled' : '') + ' aria-label="多一次">+</button></span>';
    h += '<span class="sh-opt"><i>截取</i><input class="sh-sec" type="number" inputmode="decimal" min="0" max="' + len + '" step="0.5" data-sfx-k="from" data-i="' + i + '" value="' + (o.from != null ? secText(o.from) : '') + '" placeholder="0" aria-label="从第几秒">' +
      '<i>–</i><input class="sh-sec" type="number" inputmode="decimal" min="0" max="' + len + '" step="0.5" data-sfx-k="to" data-i="' + i + '" value="' + (o.to != null ? secText(o.to) : '') + '" placeholder="' + secText(len) + '" aria-label="到第几秒"><i>秒</i></span>';
    h += def.loop ? '<span class="sh-opt"><button class="sh-chip sm on" disabled title="循环的音效一律垫着放">叠加</button></span>'
      : '<span class="sh-opt"><button class="sh-chip sm' + (o.over ? ' on' : '') + '" data-act="sfx-opt" data-k="over" data-i="' + i + '" title="叠加：垫在下一句人声底下，不等它放完">叠加</button></span>';
    h += '<button class="sh-play sm' + (on ? ' on' : '') + '" data-act="sfx-play" data-i="' + i + '"' + (pb ? ' disabled' : '') + ' aria-label="试听音效">' + (pb ? '…' : on ? '■' : '▶') + '</button>';
    return h + '</div></div>';
  }
  function renderStudio(st) {
    var h = '<div class="sh-eyebrow">REC</div><h2 class="sh-h">录音室</h2>' + sceneBar(st);
