      right = '<div class="sh-dayh">《' + esc(sess.title) + '》<small>' + esc(who ? (who.stageName || who.realName) : '?') + ' · ' + esc(sess.tier) + '</small></div>' +
        '<div class="sh-recbar"><span>已录 <b>' + rs.recorded + '</b>/' + rs.lines + ' 句 · 重录 ' + rs.retakes + ' 次</span>' +
        '<span class="sh-spd all" title="这场的语速（单句没调过的都跟它）">整场语速 ' + spdCtl(-1, lineSpd(sess, null), false) + '</span>' +
        '<button class="sh-btn" data-act="rec-all"' + (REC.all || rs.recorded >= rs.lines ? ' disabled' : '') + '>' + (REC.all ? '录音中……' : '全部录') + '</button>' +
        '<button class="sh-btn pri" data-act="rec-done"' + (REC.all ? ' disabled' : '') + '>完成</button></div>' +
        '<div class="sh-reclines">' + sess.lines.map(function (l, i) {
          var busy = !!REC.busy[l.id], aid = lineAid(l), on = AUD.curId === aid, pb = !!AUD.busy[aid];
          if (l.mute) { var so = parseSfx(l.text); return so && so.key && !so.stop ? sfxRow(l, i, so) : '<div class="sh-rl mute"><span class="no">' + String(i + 1).padStart(2, '0') + '</span><div class="tx">' + cueHtml(l.text) + '</div></div>'; }
          var eff = lineSpd(sess, l), stale = l.rec && l.spd && Math.abs(l.spd - eff) > 0.001;
