            '<div class="tx">' + cueHtml(l.text) + (l.rec ? '<span class="cnt">录了 ' + l.rec + ' 次' + (stale ? ' · 语速改了，▶ 按 ' + spdText(eff) + ' 重新合成（不算重录）' : '') + '</span>' : '') + (busy ? '<span class="cnt">录音中……</span>' : '') +
